const SAVE_DELAY_MS = 600;

/**
 * Texto que salva sozinho, um tempo depois de a pessoa parar de digitar —
 * uma requisição por pausa, não por tecla. O valor vai para `app.data` na
 * hora, para o campo não "voltar" num redesenho antes de o POST terminar.
 */
class AdminTextField extends AdminComponent {
  onremove(vnode) {
    super.onremove(vnode);

    // Sair da página no meio da pausa não pode perder o que foi digitado.
    if (this.saveTimer) {
      clearTimeout(this.saveTimer);
      this.flush();
    }
  }
  view() {
    const {
      settingKey,
      label,
      help,
      multiline,
      type = 'text',
      placeholder
    } = this.attrs;
    const value = getStr(settingKey);
    const id = `CanelaAdmin-${settingKey.replace(/\W+/g, '-')}`;
    const oninput = event => this.store(event.target.value);
    return m("div", {
      className: "Form-group"
    }, m("label", {
      className: "CanelaAdmin-label",
      for: id
    }, label), multiline ? m("textarea", {
      id: id,
      className: "FormControl CanelaAdmin-textarea",
      rows: 8,
      value: value,
      placeholder: placeholder,
      oninput: oninput
    }) : m("input", {
      id: id,
      className: "FormControl",
      type: type,
      value: value,
      placeholder: placeholder,
      oninput: oninput
    }), help && m("p", {
      className: "helpText"
    }, help));
  }
  store(value) {
    app.data.settings[this.attrs.settingKey] = value;
    clearTimeout(this.saveTimer);
    this.saveTimer = setTimeout(() => this.flush(), SAVE_DELAY_MS);
  }
  flush() {
    this.saveTimer = undefined;
    saveSetting({
      [this.attrs.settingKey]: getStr(this.attrs.settingKey)
    });
  }
}
